B.a8N=new A.ip("Arabic is written from right to left, but its numbers were borrowed by everyone.","\u0627\u0644\u0643\u062a\u0627\u0628\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0645\u0646 \u0627\u0644\u064a\u0645\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u064a\u0633\u0627\u0631\u060c \u0644\u0643\u0646 \u0627\u0644\u0639\u0627\u0644\u0645 \u0643\u0644\u0647 \u0627\u0633\u062a\u0639\u0627\u0631 \u0645\u0646\u0647\u0627 \u0627\u0644\u0623\u0631\u0642\u0627\u0645.","\ud83d\udcda")
B.a8W=new A.ip("Saudi Arabia is home to the largest sand desert in the world \u2014 the Empty Quarter.","\u062a\u0636\u0645 \u0627\u0644\u0645\u0645\u0644\u0643\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0627\u0644\u0633\u0639\u0648\u062f\u064a\u0629 \u0623\u0643\u0628\u0631 \u0635\u062d\u0631\u0627\u0621 \u0631\u0645\u0644\u064a\u0629 \u0641\u064a \u0627\u0644\u0639\u0627\u0644\u0645 \u2014 \u0627\u0644\u0631\u0628\u0639 \u0627\u0644\u062e\u0627\u0644\u064a.","\ud83c\udfdc\ufe0f")
